# Verify exact canonical polynomials, including every large rational coefficient.
@assert bytes2hex(sha256(join(string.(F), "\n") * "\n")) == "3026353b8e7168c56efe833fcd130028165943c6f90b772fc8d08ef4c3aed872"
@assert Nemo.ngens(R) == 73
@assert length(F) == 74
@assert sum(length, F) == 2706
@assert maximum(Nemo.total_degree, F) == 6
println("Julia ", VERSION, "; Nemo ", pkgversion(Nemo), "; Groebner ", pkgversion(Groebner))
println("PID ", getpid(), "; Julia threads ", Threads.nthreads())
println("Exact input verified: 74 polynomials, 73 variables, 2706 terms, degree <= 6; QQ, degrevlex.")
flush(stdout)

if ARGS != ["--check"]
    println("Calling Groebner.groebner(F) with the production defaults; no time limit.")
    flush(stdout)
    started_ns = time_ns()
    try
        gb = Groebner.groebner(F)
        println("Returned ", length(gb), " basis polynomials after ", (time_ns() - started_ns) / 1e9, " seconds.")
    catch err
        println(stderr, "Groebner call ended after ", (time_ns() - started_ns) / 1e9, " seconds: ", typeof(err))
        rethrow()
    end
end
